/* Repo-skill content pins (generated by scripts/ingest.mjs from the same files the runtime executes). */
import pins from "../../data/content-pins.json" with { type: "json" };
import skillShas from "../../data/skill-shas.json" with { type: "json" };
import type { VersionSource } from "./db.ts";

const PINS = pins as Record<string, string>;
export const currentPin = (repoSkill: string | undefined): string | null => (repoSkill ? PINS[repoSkill] ?? null : null);
const OWN = skillShas as Record<string, string>;
/** Hash of a repo skill's own files in this deployment (no shared runner) — compared with a frozen version's files. */
export const currentSkillSha = (repoSkill: string | undefined): string | null => (repoSkill ? OWN[repoSkill] ?? null : null);

export type PinState = { ok: true; note: string | null } | { ok: false; reason: string };

/** Drafts run whatever the deployment holds (they are being worked on). Any version past draft must run on the exact
 *  files it was reviewed with; versions created before pinning existed run with a recorded note. */
export function checkPin(source: VersionSource, status: string | undefined): PinState {
  if (source.kind !== "repo") return { ok: true, note: null };
  const now = currentPin(source.repo_skill);
  if (!now) return { ok: false, reason: `repository skill ${source.repo_skill} is not in this deployment` };
  if (!status || status === "draft") return { ok: true, note: source.content_sha && source.content_sha !== now ? "draft runs the deployed repository files (changed since this draft was pinned)" : null };
  if (!source.content_sha) return { ok: true, note: "version created before content pinning — files not verified" };
  if (source.content_sha !== now) return { ok: false, reason: `repository files changed since this version left draft (pinned ${source.content_sha.slice(0, 12)}…, deployed ${now.slice(0, 12)}…). Create a new draft version.` };
  return { ok: true, note: null };
}
